      ro: ["Golful cuprinde un total de 1.969 de insule de calcar de diferite dimensiuni.", "UNESCO a declarat golful sit al Patrimoniului Mondial în 1994.", "Peștera Sung Sot (Peștera Surpriză) este una dintre cele mai mari din regiune.", "Aproximativ 1.600 de oameni trăiesc permanent în sate de pescari plutitoare.", "Stâncile de calcar din golf au o vechime de aproximativ 500 de milioane de ani.", "Ha Long se traduce prin 'Dragonul care coboară'."],
