      en: "A national park and UNESCO World Heritage site, noted for its hundreds of cave systems, including the world's largest cave.",
      es: "Un parque nacional y Patrimonio de la Humanidad por la UNESCO, conocido por sus cientos de sistemas de cuevas, incluida la cueva más grande del mundo.",
      pt: "Um parque nacional e Património Mundial da UNESCO, conhecido pelas suas centenas de sistemas de cavernas, incluindo a maior caverna do mundo.",
