      en: "A towering white statue of the Goddess of Mercy, Guanyin, standing on the Sơn Trà Peninsula, looking out to sea.",
      es: "Una imponente estatua blanca de la diosa de la misericordia, Guanyin, situada en la península de Sơn Trà frente al mar.",
      pt: "Uma imponente estátua branca da deusa da misericórdia, Guanyin, situada na península de Sơn Trà com vista para o mar.",
      fr: "Une imposante statue blanche de la déesse de la miséricorde, Guanyin, dressée sur la péninsule de Sơn Trà et dominant la mer.",
