      ro: ["O catedrală în centrul orașului Ho Și Min, construită de coloniștii francezi între 1863 și 1880.", "Se află pe teritoriul Republicii Socialiste Vietnam.", "Are un rol în identitatea locală a regiunii.", "Este cunoscut pentru semnificația sa peisagistică sau culturală."],
      en: ["A cathedral located in the downtown of Ho Chi Minh City, constructed by the French colonists between 1863 and 1880.", "Located within the Socialist Republic of Vietnam.", "Plays a role in the local identity of the region.", "Known for its scenic or cultural significance."],
      es: ["Una catedral en el centro de la ciudad de Ho Chi Minh, construida por colonos franceses entre 1863 y 1880.", "Se encuentra en el territorio de la República Socialista de Vietnam.", "Desempeña un papel en la identidad local de la región.", "Conocido por su importancia paisajística o cultural."],
      pt: ["Uma catedral no centro da cidade de Ho Chi Minh, construída por colonos franceses entre 1863 e 1880.", "Situa-se no território da República Socialista do Vietname.", "Desempenha um papel na identidade local da região.", "Conhecido pela sua importância paisagística ou cultural."],
      fr: ["Une cathédrale au centre d'Hô Chi Minh-Ville, construite par les colons français entre 1863 et 1880.", "Situé sur le territoire de la République socialiste du Vietnam.", "Joue un rôle dans l'identité locale de la région.", "Connu pour son importance paysagère ou culturelle."],
