      pt: ["Uma vasta região no sudoeste do Vietname, onde o Mekong desagua no mar. É uma paisagem exuberante com campos de arroz, canais e mercados flutuantes.", "Situa-se no território da República Socialista do Vietname.", "Desempenha um papel na identidade local da região.", "Conhecido pela sua importância paisagística ou cultural."],
